local f=workspace.Installation4 local b=game.ServerStorage:FindFirstChild("AnciensScripts") or Instance.new("Folder",game.ServerStorage) b.Name="AnciensScripts" for n,p in {GrassServer=game.ServerScriptService,GrassClient=game.StarterPlayer.StarterPlayerScripts,BarreOutils=game.StarterPlayer.StarterPlayerScripts} do local v=p:FindFirstChild(n) while v do v.Enabled=false v.Name=n.."_ANCIEN" v.Parent=b v=p:FindFirstChild(n) end f[n].Parent=p end f:Destroy() local c=game.ReplicatedStorage:FindFirstChild("GrassConfig") if c then c.Source=c.Source:gsub("SCISSORS_EXTRA = %d+","SCISSORS_EXTRA = 0") end print("Installation OK !")
